          var bg = pick(r, ['#F1ECE2', '#2E2A27', '#7B3F32', '#2F4A45', null]), fg = bg === '#F1ECE2' ? '#2E2A27' : (bg ? '#F4EBD9' : pick(r, ['#2E2A27', '#7B3F32', '#F4EBD9']));
