    sh.quadraticCurveTo(X1, -zB, X1 - cr, -zB); sh.lineTo(X0 + cr, -zB); sh.quadraticCurveTo(X0, -zB, X0, -zB - cr);
    sh.lineTo(X0, -zF + cr); sh.quadraticCurveTo(X0, -zF, X0 + cr, -zF);
