      kit.box('pipe', a[0], 1.05, a[1], 0.06, 2.1, 0.06);
      [0.35, 0.75, 1.15, 1.55, 1.95].forEach(function (y) { kit.put('pipe', plc2_seg(a[0], y, a[1], b[0], y, b[1], 0.038)); });
