        cc.copy(cg).lerp(cd2, sstep(0.45, 0.75, n) * 0.7).multiplyScalar(0.85 + 0.3 * fbm(x / 1.5, z / 1.5, sd + 62, 2));
        col.push(cc.r, cc.g, cc.b);
