    var src = T['Pages'] === 'Departures' ? var_departurePages : T['Pages'] === 'Almanac' ? var_almanacPages : boardPages;
    var cols = 18, cw = 0.34, ch = 0.46, gap = 0.035, Wb = cols * (cw + gap) + 0.5;
    var bw = 0.78, bh = 1.06, legH = rf(r, 1.2, 2.0);
