    sh.lineTo(x0 + Wm, y0 + Hm - rad); sh.quadraticCurveTo(x0 + Wm, y0 + Hm, x0 + Wm - rad, y0 + Hm);
    sh.lineTo(x0 + rad, y0 + Hm); sh.quadraticCurveTo(x0, y0 + Hm, x0, y0 + Hm - rad);
