    glass.position.set(0, cy - 0.1, z + 0.12); b.add(glass);
    var fm = var_flapMaterial(W, T['Flaps']), bw = 1.02, bh = 1.62, gap = 0.07, zz = z + 0.05;
    var xs = -(Wm - 0.7) / 2 + 0.22, xS = xs + 4 * (bw + gap) + 0.38;
