    mk.position.set(Wm / 2 - 0.9, cy - Hm / 2 + 0.2, z); b.add(mk);
    if (stance !== 'Tipped Back') [-1, 1].forEach(function (sd) {
      var ft = cyl(0.22, 0.3, legH + 0.14, 16, std('#1A1B1E', 0.5, 0.6)); ft.position.set(sd * (Wm / 2 - 1.1), (legH + 0.14) / 2, 0); b.add(ft);
    });
