    var r = W.r, g = new THREE.Group(), hm = heroMat(matName);
    var T = W.P.clockTraits || {}, rs = T['Rings'] || 'Wire', nMoons = { 'One': 1, 'Two': 2, 'Three': 3 }[T['Moons']] || 0;
