    return [a * SOL_Q[0] + b * SOL_E[0] + c * SOL_P[0], a * SOL_Q[1] + b * SOL_E[1] + c * SOL_P[1], a * SOL_Q[2] + b * SOL_E[2] + c * SOL_P[2]];
