  function sol_circle(rad, n, a0) { var p = []; for (var i = 0; i < n; i++) { var a = (a0 || 0) + i / n * SOL_TAU; p.push(new THREE.Vector2(rad * Math.cos(a), rad * Math.sin(a))); } return p; }
