      gc.font = '400 30px ' + FONT_MONO;
      gc.fillText('MARFA 30.31 N   ' + (D === 0 ? 'FACING DUE SOUTH' : 'DECLINING ' + Math.abs(D) + (D > 0 ? ' WEST' : ' EAST')) + '   ' + (dst ? 'CDT' : 'CST'), X(fx), Y0 - bd - HB * 0.13);
