        gc.fillStyle = sol_mix('#EFE7D4', '#B3A690', 0.45 + rr() * 0.35); gc.beginPath(); gc.ellipse(px, py, pr * 0.8, pr * (0.3 + rr() * 0.6), rr() * 3, 0, SOL_TAU); gc.fill();
