    var r = W.r, T = W.P.clockTraits, md = MATERIALS[matName], dst = W.dst, g = new THREE.Group();
    var metal = sol_hero(matName), gilt = sol_gilt(), dark = sol_iron(), roman = T['Numerals'] === 'Roman';
    var ink = sol_ink(md.color), off = dst ? -5 : -6;
