    var tower = heroMat(matName), darkM = std('#1C1D20', 0.5, 0.6), concM = mtl('#A9A294', 'concrete', 0.95, 0, 1.6);
    var galv = mtl('#B9BEC2', 'brushed', 0.42, 0.85, 0.6), woodM = mtl('#8A7157', 'wood', 0.95, 0, 0.7);
