      g.add(new THREE.Mesh(new THREE.TubeBufferGeometry(path, used.length * 8, 0.012, 5, true), std(pick(W.r, ['#D1495B', '#1D1D1F', BRAND.blue, '#EDAE49']), 0.6)));
