        if (state === 'A') rows = page ? [['ON TIME', 'A'], ['MARFA', clock]] : [['NEXT TRAIN', 'A'], ['317 LOCAL', rem ? rem + ' MIN' : 'NOW']];
        else if (state === 'B') rows = page ? [['SIGNAL PROBLEMS', 'B'], ['MARFA', clock]] : [['NEXT TRAIN', 'B'], ['DELAYED', '+17 MIN']];
