      var sc = pick(r, schemes), bg = sc[0], pal = sc[1], sunX = rf(r, 0.25, 0.75), hills = [];
      for (k = 0; k < 3; k++) hills.push([rf(r, 0.1, 0.9), rf(r, 0.1, 0.25), rf(r, 0.5, 1)]);
