    var S = { W: W, hero: hero, g: g, r: seedRng(g.seed), cd: cd, R: hero.R, H: cd.height || hero.lookY * 2,
      fov: GEN_FOV[g.lens] || 38, shift: gen_shift(g), box: new THREE.Group(), heroPick: null };
