    box.style.cssText = 'position:fixed;left:-20000px;top:0;width:' + size + 'px;height:' + size + 'px;overflow:hidden;opacity:0;pointer-events:none';
    (real.body || real.documentElement).appendChild(box);
    var body = { style: {}, prepend: function (c) { box.appendChild(c); }, appendChild: function (c) { box.appendChild(c); } };
