          var gc = c.getContext.bind(c);
          c.getContext = function (k, o) { o = o || {}; if (k !== '2d') o.preserveDrawingBuffer = true; c.__kind = k; var x = gc(k, o); if (k !== '2d') c.__ctx = x; return x; };
