            cm = gl.getParameter(gl.COLOR_WRITEMASK), dm = gl.getParameter(gl.DEPTH_WRITEMASK), dc = gl.getParameter(gl.DEPTH_CLEAR_VALUE);
          gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.disable(gl.SCISSOR_TEST); gl.colorMask(true, true, true, true); gl.depthMask(true);
          gl.clearColor(0, 0, 0, 0); gl.clearDepth(1); gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT | gl.STENCIL_BUFFER_BIT);
