      var ang = r() * Math.PI * 2, rad = S.R + rf(r, 1.2, pass < 2 ? 6 : 16), D = rf(r, 5.5, 12);
      var mx = Math.cos(ang) * rad, mz = Math.sin(ang) * rad, my = aln_gy(W, mx, mz);
