    var ringM = new THREE.Mesh(new THREE.TorusBufferGeometry(0.2, 0.008, 6, 48), mtl('#3A2E20', 'brushed', 0.6, 0.6, 0.6)); ringM.rotation.x = -Math.PI / 2; ringM.position.y = 0.022; mk.add(ringM);
